'use strict';

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function lexicalCompare(a, b) {
  return a < b ? -1 : a > b ? 1 : 0;
}

function applyPatchSet(catalog, operations) {
  if (!isPlainObject(catalog) || !Array.isArray(operations) ||
      Object.getOwnPropertySymbols(catalog).length !== 0) {
    throw new TypeError('invalid arguments');
  }

  function cleanKey(value) {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new TypeError('invalid key');
    }
    return value.trim();
  }

  function cleanValue(value) {
    if (!isPlainObject(value) ||
        !Object.hasOwn(value, 'label') || !Object.hasOwn(value, 'score') ||
        typeof value.label !== 'string' || value.label.trim() === '' ||
        typeof value.score !== 'number' || !Number.isFinite(value.score)) {
      throw new TypeError('invalid value');
    }
    return { label: value.label.trim(), score: value.score };
  }

  const work = catalog;

  for (const rawKey of Object.keys(catalog)) {
    const key = cleanKey(rawKey);
    work[key] = cleanValue(catalog[rawKey]);
  }

  for (const operation of operations) {
    if (!isPlainObject(operation) ||
        !Object.hasOwn(operation, 'kind') || !Object.hasOwn(operation, 'key') ||
        typeof operation.kind !== 'string') {
      throw new TypeError('invalid operation');
    }

    const key = cleanKey(operation.key);

    if (operation.kind === 'put') {
      if (!Object.hasOwn(operation, 'value')) {
        throw new TypeError('invalid operation');
      }
      work[key] = cleanValue(operation.value);
    } else if (operation.kind === 'remove') {
      if (!Object.hasOwn(work, key)) {
        throw new RangeError('unknown key');
      }
      delete work[key];
    } else {
      throw new TypeError('invalid operation kind');
    }
  }

  const result = Object.create(null);
  for (const key of Object.keys(work).sort(lexicalCompare)) {
    result[key] = { ...work[key] };
  }
  return result;
}

module.exports = { applyPatchSet };

