'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['applyPatchSet']);
const { applyPatchSet } = api;

const catalog = {
  z: { label: 'Zulu', score: 9 },
  a: { label: 'Alpha', score: 1 }
};
const detached = applyPatchSet(catalog, []);
assert.strictEqual(Object.getPrototypeOf(detached), null);
assert.deepStrictEqual(Object.keys(detached), ['a', 'z']);
assert.deepStrictEqual({ ...detached }, {
  a: { label: 'Alpha', score: 1 },
  z: { label: 'Zulu', score: 9 }
});
assert.notStrictEqual(detached.a, catalog.a);
detached.a.score = 100;
assert.strictEqual(catalog.a.score, 1);
catalog.z.label = 'changed';
assert.strictEqual(detached.z.label, 'Zulu');

const value = { label: '  Beta  ', score: 2.5 };
const result = applyPatchSet(catalog, [
  { kind: 'put', key: ' b ', value },
  { kind: 'remove', key: 'a' },
  { kind: 'put', key: 'a', value: { label: 'New A', score: 3 } },
  { kind: 'put', key: 'b', value: { label: 'Final B', score: 4 } }
]);
assert.strictEqual(Object.getPrototypeOf(result), null);
assert.deepStrictEqual(Object.keys(result), ['a', 'b', 'z']);
assert.deepStrictEqual({ ...result }, {
  a: { label: 'New A', score: 3 },
  b: { label: 'Final B', score: 4 },
  z: { label: 'changed', score: 9 }
});
value.label = 'mutated';
assert.strictEqual(result.b.label, 'Final B');
assert.deepStrictEqual(Object.keys(catalog), ['z', 'a']);
assert.strictEqual(catalog.a.score, 1);

const atomicCatalog = { keep: { label: 'Keep', score: 5 } };
const before = JSON.stringify(atomicCatalog);
assert.throws(() => applyPatchSet(atomicCatalog, [
  { kind: 'put', key: 'new', value: { label: 'New', score: 1 } },
  { kind: 'remove', key: 'missing' }
]), RangeError);
assert.strictEqual(JSON.stringify(atomicCatalog), before);

for (const badCatalog of [null, [], new Date()]) {
  assert.throws(() => applyPatchSet(badCatalog, []), TypeError);
}
assert.throws(() => applyPatchSet({}, null), TypeError);
assert.throws(() => applyPatchSet({}, [{ kind: 'put', key: '', value: { label: 'x', score: 1 } }]), TypeError);
assert.throws(() => applyPatchSet({}, [{ kind: 'put', key: 'x', value: { label: '', score: 1 } }]), TypeError);
assert.throws(() => applyPatchSet({}, [{ kind: 'put', key: 'x', value: { label: 'x', score: Infinity } }]), TypeError);
assert.throws(() => applyPatchSet({}, [{ kind: 'remove' }]), TypeError);
assert.throws(() => applyPatchSet({}, [{ kind: 'unknown', key: 'x' }]), TypeError);
assert.throws(() => applyPatchSet({ x: { label: 'x', score: NaN } }, []), TypeError);

